// Delivery controls only. Define categories in Configure Label Rules.
const config = {
  "mode": "gmail",
  "dry_run": false,
  "allow_create_labels": true,
  "allow_archive": false,
  "allow_mark_read": false,
  "mailbox_key": "gmail-primary",
  "rule_version": "rules-v2.1",
  "min_margin": 10
};
return $input.all().map((item,index) => ({json:{raw:item.json,config},pairedItem:{item:index}}));

const context = $('Configure Gmail Triage').item.json;
const ok = $json.statusCode === 200 && $json.body?.id === context.raw.id;
return {json:{config:context.config,raw:ok ? $json.body : {id:context.raw.id,_fetch_error:true}}};

// Handles Gmail REST format=full, simplified fields, and parsed IMAP-style objects.
return $input.all().map((entry, index) => {
  const { raw, config, rules } = entry.json;
  const issues = [], warnings = [];
  const obj = x => x !== null && typeof x === 'object' && !Array.isArray(x);
  const r = obj(raw) ? raw : {};
  if (!obj(raw)) issues.push('email_must_be_object');
  const headers = Object.create(null);
  function addHeader(key, value) {
    if (typeof key !== 'string' || value == null || value === '') return;
    if (Array.isArray(value)) value = value.filter(x => typeof x === 'string').join(' ');
    if (typeof value !== 'string') { issues.push('invalid_header_value'); return; }
    const k = key.toLowerCase();
    const combined = [headers[k], value].filter(Boolean).join(' ');
    if (combined.length > 8000) warnings.push('header_truncated');
    headers[k] = combined.slice(0, 8000);
  }
  const h = r.payload?.headers ?? r.headers ?? {};
  if (Array.isArray(h)) h.forEach(v => obj(v) ? addHeader(v.name, v.value) : issues.push('invalid_header'));
  else if (obj(h)) Object.entries(h).forEach(([k,v]) => addHeader(k,v));
  else issues.push('invalid_headers');
  const getString = (value, fallback = '') => {
    if (value == null) return fallback;
    if (typeof value !== 'string') { issues.push('invalid_text_field'); return fallback; }
    return value;
  };
  const fromValue = r.from ?? r.From ?? headers.from ?? '';
  const fromRaw = obj(fromValue) ? fromValue.value?.[0]?.address ?? fromValue.text ?? '' : getString(fromValue);
  const from = (String(fromRaw).match(/<([^<>]+)>/)?.[1] ?? String(fromRaw)).trim().toLowerCase();
  const subject = getString(r.subject ?? r.Subject, headers.subject ?? '');
  const textParts = [], htmlParts = [], attachments = [];
  let partsSeen = 0;
  function walk(part, depth = 0) {
    if (!obj(part)) { issues.push('invalid_mime_part'); return; }
    if (++partsSeen > 100 || depth > 10) { warnings.push('mime_limit_exceeded'); return; }
    if (typeof part.filename === 'string' && part.filename) attachments.push({ filename: part.filename.slice(0, 255) });
    if (!part.filename && typeof part.body?.data === 'string' && ['text/plain','text/html'].includes(part.mimeType)) {
      if (part.body.data.length > 100000) warnings.push('body_truncated');
      const decoded = Buffer.from(part.body.data.slice(0,100000), 'base64url').toString('utf8');
      (part.mimeType === 'text/plain' ? textParts : htmlParts).push(decoded);
    }
    if (part.parts !== undefined && !Array.isArray(part.parts)) issues.push('invalid_mime_parts');
    if (Array.isArray(part.parts)) part.parts.slice(0,101).forEach(p => walk(p, depth+1));
  }
  if (r.payload !== undefined) walk(r.payload);
  if (r.payload && !textParts.length && !htmlParts.length && !r.text && !r.body && !r.html) warnings.push('body_unavailable_snippet_only');
  if (r.attachments !== undefined && !Array.isArray(r.attachments)) issues.push('invalid_attachments');
  if (Array.isArray(r.attachments)) {
    if (r.attachments.length > 100) warnings.push('attachment_limit_exceeded');
    for (const a of r.attachments.slice(0,100)) {
      if (!obj(a) || typeof a.filename !== 'string') issues.push('invalid_attachment');
      else attachments.push({ filename: a.filename.slice(0,255) });
    }
  }
  const rawHtml = getString(r.html, htmlParts.join('\n'));
  if (rawHtml.length > 50000) warnings.push('html_truncated');
  const html = rawHtml.slice(0,50000);
  const strippedHtml = html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,' ').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,' ').replace(/<[^>]*>/g,' ').replace(/&nbsp;|&#160;/g,' ').replace(/&amp;/g,'&');
  const body = getString(r.text ?? r.body, textParts.join('\n') || strippedHtml || getString(r.snippet));
  if (subject.length > 1000 || body.length > 50000) warnings.push('text_truncated');
  if ('custom_taxonomy' in r) issues.push('message_supplied_rules_not_allowed_use_configure_node');
  if (r.error || r._fetch_error) issues.push('gmail_fetch_failed');
  const id = typeof r.id === 'string' ? r.id : '';
  // Never substitute RFC Message-ID for the Gmail REST message ID.
  return { json: { config, rules, issues: [...new Set(issues)], warnings: [...new Set(warnings)], content_incomplete: warnings.length > 0, email: { provider_message_id: id, from, subject: subject.slice(0,1000), body: body.slice(0,50000), headers, attachments, label_ids: Array.isArray(r.labelIds) ? r.labelIds.filter(v => typeof v === 'string') : [] } }, pairedItem: { item: index } };
});

const seen = new Set();
const validLabel = name => typeof name === 'string' && name.length > 0 && name.length <= 200 && name === name.trim() && !/[\x00-\x1f\x7f]/.test(name) && !name.split('/').some(part => !part.trim()) && !/^(INBOX|SPAM|TRASH|UNREAD|STARRED|IMPORTANT|SENT|DRAFT|DRAFTS|CHAT|CHATS|ALL|ALL MAIL|CATEGORY_.*)$/i.test(name);
return $input.all().map((entry,index) => {
  const x = entry.json, issues = [...x.issues], c = x.config, e = x.email;
  const obj = v => v !== null && typeof v === 'object' && !Array.isArray(v);
  if (!e.provider_message_id || e.provider_message_id.length > 256) issues.push('missing_or_invalid_message_id');
  if (c.mode === 'gmail' && !/^[a-f0-9]+$/i.test(e.provider_message_id)) issues.push('invalid_gmail_message_id');
  if (!/^[^\s<>@]+@[^\s<>@]+\.[^\s<>@]+$/.test(e.from)) issues.push('invalid_sender');
  if (!e.subject && !e.body) issues.push('empty_message');
  if (!obj(c.safety_labels) || !validLabel(c.safety_labels.security) || !validLabel(c.safety_labels.critical) || typeof c.safety_labels.create_if_missing !== 'boolean') issues.push('invalid_safety_label_config');
  const key = `${c.mailbox_key}:${e.provider_message_id}`;
  if (seen.has(key)) issues.push('duplicate_in_batch');
  seen.add(key);
  for (const flag of ['dry_run','allow_create_labels','allow_archive','allow_mark_read']) if (typeof c[flag] !== 'boolean') issues.push(`invalid_config_${flag}`);
  if (!['demo','gmail'].includes(c.mode) || typeof c.mailbox_key !== 'string' || !c.mailbox_key.trim() || typeof c.rule_version !== 'string' || !c.rule_version.trim()) issues.push('invalid_config_identity');
  if (!Number.isFinite(c.min_margin) || c.min_margin < 0 || c.min_margin > 100) issues.push('invalid_margin');
  if (!Array.isArray(x.rules) || !x.rules.length || x.rules.length > 30) issues.push('invalid_rules_array');
  else {
    const ids = new Set();
    for (const rule of x.rules) {
      if (!obj(rule)) { issues.push('invalid_rule_object'); continue; }
      if (typeof rule.id !== 'string' || !/^[a-z0-9_]{1,64}$/.test(rule.id) || ids.has(rule.id)) issues.push('invalid_or_duplicate_rule_id');
      ids.add(rule.id);
      if (!validLabel(rule.label)) issues.push('invalid_label_name');
      if (rule.enabled !== undefined && typeof rule.enabled !== 'boolean') issues.push('invalid_rule_enabled');
      if (rule.create_if_missing !== undefined && typeof rule.create_if_missing !== 'boolean') issues.push('invalid_rule_create_if_missing');
      for (const field of ['priority','min_score']) if (!Number.isFinite(rule[field]) || rule[field] < 0 || rule[field] > 200) issues.push(`invalid_rule_${field}`);
      if (!obj(rule.actions) || Object.keys(rule.actions).some(k => !['star','archive','mark_read'].includes(k)) || ['star','archive','mark_read'].some(k => typeof rule.actions[k] !== 'boolean')) issues.push('invalid_rule_actions');
      if (!obj(rule.signals)) { issues.push('invalid_rule_signals'); continue; }
      if (Object.keys(rule.signals).some(k => !['senders','subject_terms','body_terms','extensions','headers'].includes(k))) issues.push('unsupported_signal_use_literal_terms');
      for (const field of ['senders','subject_terms','body_terms','extensions']) {
        const list = rule.signals[field] ?? [];
        if (!Array.isArray(list) || list.length > 30 || list.some(v => typeof v !== 'string' || !v.trim() || v.length > 160)) { issues.push(`invalid_signal_${field}`); continue; }
        if (field === 'senders' && list.some(v => !/^(\*|[a-z0-9.!#$%&'+/=?^_`{|}~-]+)@(?:[a-z0-9-]+\.)+[a-z]{2,}$/i.test(v))) issues.push('sender_must_be_exact_address_or_domain_wildcard');
        if (field === 'extensions' && list.some(v => !/^\.[a-z0-9]{1,10}$/i.test(v))) issues.push('invalid_extension');
      }
      const headers = rule.signals.headers ?? {};
      if (!obj(headers) || Object.keys(headers).length > 10) issues.push('invalid_rule_headers');
      else for (const [key,value] of Object.entries(headers)) if (!/^[a-z0-9-]{1,80}$/.test(key) || !(value === true || (Array.isArray(value) && value.length > 0 && value.length <= 10 && value.every(v => typeof v === 'string' && v.length > 0 && v.length <= 80)))) issues.push('invalid_header_rule');
    }
  }
  return { json: { ...x, issues: [...new Set(issues)], valid: issues.length === 0 }, pairedItem: { item: index } };
});

return $input.all().map((entry,index) => {
  const x = entry.json, e = x.email;
  const candidates = [];
  if (x.valid) for (const rule of x.rules) {
    if (rule.enabled === false) continue;
    let score = 0; const evidence = [], s = rule.signals;
    const sender = (s.senders ?? []).find(v => v.startsWith('*@') ? e.from.split('@')[1] === v.slice(2).toLowerCase() : e.from === v.toLowerCase());
    if (sender) { score += 30; evidence.push({ signal: 'sender', rule: sender, weight: 30 }); }
    for (const [field,weight] of [['subject_terms',25],['body_terms',15]]) {
      const value = (field === 'subject_terms' ? e.subject : e.body).toLowerCase();
      const hits = (s[field] ?? []).filter(term => value.includes(term.toLowerCase()));
      if (hits.length) { score += weight; evidence.push({ signal: field, rules: hits, weight }); }
    }
    const headerHits = Object.entries(s.headers ?? {}).filter(([key,values]) => {
      const actual = e.headers[key]?.toLowerCase().trim();
      return !!actual && (values === true || values.some(v => actual.split(';')[0].trim() === v.toLowerCase()));
    }).map(([key]) => key);
    // Cap the whole header vector: two bulk headers do not count as independent proof.
    if (headerHits.length) { score += 40; evidence.push({ signal: 'headers', rules: headerHits, weight: 40 }); }
    const extHits = (s.extensions ?? []).filter(ext => e.attachments.some(a => a.filename.toLowerCase().endsWith(ext.toLowerCase())));
    if (extHits.length) { score += 15; evidence.push({ signal: 'extensions', rules: extHits, weight: 15 }); }
    if (score >= rule.min_score) candidates.push({ id: rule.id, label: rule.label, score, priority: rule.priority, evidence, actions: rule.actions, create_if_missing: rule.create_if_missing !== false });
  }
  candidates.sort((a,b) => b.score-a.score || b.priority-a.priority || a.id.localeCompare(b.id));
  return { json: { ...x, candidates, classification: candidates[0] ?? null }, pairedItem: { item: index } };
});

return $input.all().map((entry,index) => {
  const x = entry.json, reasons = [...x.issues], text = `${x.email.subject}\n${x.email.body}`.toLowerCase();
  const protectedKinds = [];
  if (/\b(?:otp|verification code|one[- ]time password|password reset|reset password|security alert|suspicious login|kode verifikasi|kode keamanan|reset kata sandi)\b/i.test(text)) protectedKinds.push('security');
  if (/\b(?:build failed|deployment failed|deploy failed|pipeline failed|production down|service down|outage|critical alert|incident|severity[ :_-]*[01]|sev[ -]?[01]|p[01] incident|gagal deploy|layanan mati)\b/i.test(text)) protectedKinds.push('critical_alert');
  let decision = !x.valid ? 'needs_review' : x.classification ? 'actionable' : 'keep_in_inbox';
  let chosen = x.classification;
  if (x.valid && protectedKinds.length) {
    const security = protectedKinds.includes('security');
    chosen = { id: security ? 'protected_security' : 'protected_critical', label: security ? x.config.safety_labels.security : x.config.safety_labels.critical, create_if_missing: x.config.safety_labels.create_if_missing, score: null, priority: 200, evidence: [{ signal: 'safety_policy', rules: protectedKinds }], actions: { star: true, archive: false, mark_read: false } };
    decision = 'actionable'; reasons.push('protected_message_keep_unread');
  } else if (x.valid && x.candidates.length > 1 && x.candidates[0].score-x.candidates[1].score <= x.config.min_margin) {
    decision = 'needs_review'; reasons.push('ambiguous_category_scores');
  }
  if (x.valid && !chosen) reasons.push('no_rule_reached_threshold');
  if (x.content_incomplete) reasons.push('incomplete_content_no_archive_or_mark_read');
  return { json: { ...x, classification: chosen, decision, reasons, protected_kinds: protectedKinds }, pairedItem: { item: index } };
});

return $input.all().map((entry,index) => {
  const x = entry.json, c = x.config, actionable = x.decision === 'actionable';
  const a = actionable ? x.classification.actions : { star:false, archive:false, mark_read:false };
  const protectedMessage = x.protected_kinds.length > 0 || x.content_incomplete === true;
  const add = a.star ? ['STARRED'] : [], remove = [];
  if (!protectedMessage && a.archive && c.allow_archive) remove.push('INBOX');
  if (!protectedMessage && a.mark_read && c.allow_mark_read) remove.push('UNREAD');
  const reasons = [...x.reasons];
  if (a.archive && !c.allow_archive) reasons.push('archive_disabled_by_config');
  if (a.mark_read && !c.allow_mark_read) reasons.push('mark_read_disabled_by_config');
  const plan = { label_name: actionable ? x.classification.label : null, create_if_missing: actionable && x.classification.create_if_missing !== false, add_label_ids: add, remove_label_ids: remove };
  const dry = c.mode !== 'gmail' || c.dry_run !== false;
  const envelope = {
    schema_version:'2.1', provider:c.mode === 'gmail' ? 'gmail' : 'fixture', mailbox_key:c.mailbox_key,
    provider_message_id:x.email.provider_message_id || null, rule_version:c.rule_version,
    decision:x.decision, status:x.decision === 'needs_review' ? 'needs_review' : x.decision === 'keep_in_inbox' ? 'kept' : 'planned',
    dry_run:dry, reasons, warnings:x.warnings ?? [], content_incomplete:x.content_incomplete === true, protected_kinds:x.protected_kinds,
    classification: x.classification ? { category_id:x.classification.id, label:x.classification.label, score:x.classification.score, evidence:x.classification.evidence } : null,
    candidates:x.candidates.map(v => ({ category_id:v.id, label:v.label, score:v.score })),
    requested_actions:{ ...a }, action_plan:plan,
    // Deterministic reference only. This is NOT a durable deduplication lock.
    operation_key:JSON.stringify([c.mailbox_key,x.email.provider_message_id,c.rule_version,plan]),
    delivery:{ attempted:false, http_status:null, error_code:null },
    config:{ allow_create_labels:c.allow_create_labels === true }
  };
  return { json:envelope, pairedItem:{ item:index } };
});

// EDIT HERE: use exact existing Gmail names or desired new names.
// enabled: false pauses a rule. create_if_missing requires the global allow_create_labels switch too.
// Subject match = 25 points; use min_score=25 to allow subject-only classification.
