return $input.all().map((item,index) => ({json:{...item.json,config:{...item.json.config,safety_labels},rules},pairedItem:{item:index}}));

const p = $('Build Gmail Action Plan').item.json;
const response = $json;
const code = Number(response.statusCode) || null;
const fail = reason => ({ json:{ ...p, decision:'needs_review', status:'needs_review', resolution:'review', reasons:[...p.reasons,reason], delivery:{ attempted:false,http_status:code,error_code:reason } } });
if (code !== 200 || !Array.isArray(response.body?.labels)) return fail('gmail_label_list_failed');
const matches = response.body.labels.filter(l => l.name === p.action_plan.label_name && l.type === 'user' && typeof l.id === 'string');
if (matches.length > 1) return fail('ambiguous_label_mapping');
if (matches.length === 1) return { json:{ ...p, resolution:'ready', resolved_label_id:matches[0].id } };
if (p.config.allow_create_labels && p.action_plan.create_if_missing !== false && !p.dry_run) return { json:{ ...p,resolution:'create' } };
return fail('label_missing_creation_disabled');

const p = $('Resolve Gmail Label').item.json;
const status = Number($json.statusCode) || null;
// Another execution may have created the same label. Re-fetch once on 409.
if ((status >= 200 && status < 300) || status === 409) return { json:{ ...p,resolution:'refresh',label_creation_status:status } };
return { json:{ ...p,decision:'needs_review',status:'needs_review',resolution:'review',reasons:[...p.reasons,'gmail_label_create_failed'],delivery:{ attempted:false,http_status:status,error_code:'gmail_label_create_failed' } } };

const p = $('Check Label Creation').item.json;
const status = Number($json.statusCode) || null;
const matches = status === 200 && Array.isArray($json.body?.labels) ? $json.body.labels.filter(l => l.name === p.action_plan.label_name && l.type === 'user' && typeof l.id === 'string') : [];
if (matches.length === 1) return { json:{ ...p,resolution:'ready',resolved_label_id:matches[0].id } };
return { json:{ ...p,decision:'needs_review',status:'needs_review',resolution:'review',reasons:[...p.reasons,'label_unresolved_after_create'],delivery:{ attempted:false,http_status:status,error_code:'label_unresolved_after_create' } } };

return $input.all().map((item,index) => {
  const p = item.json;
  const add = [...new Set([...p.action_plan.add_label_ids,p.resolved_label_id])].filter(Boolean);
  const remove = [...new Set(p.action_plan.remove_label_ids)];
  const valid = p.provider === 'gmail' && p.dry_run === false && p.decision === 'actionable' && p.resolution === 'ready' && typeof p.resolved_label_id === 'string' && /^Label_/.test(p.resolved_label_id) && /^[a-f0-9]+$/i.test(p.provider_message_id) && remove.every(id => ['INBOX','UNREAD'].includes(id)) && !((p.protected_kinds.length || p.content_incomplete) && remove.length) && !add.some(id => remove.includes(id));
  if (!valid) return { json:{ ...p,decision:'needs_review',status:'needs_review',ready_to_modify:false,reasons:[...p.reasons,'unsafe_or_incomplete_modify_plan'] },pairedItem:{item:index} };
  const action_plan = { ...p.action_plan,add_label_ids:add,remove_label_ids:remove };
  return { json:{ ...p,action_plan,ready_to_modify:true,modify_body:{ addLabelIds:add,removeLabelIds:remove } },pairedItem:{item:index} };
});

const p = $('Build Gmail Modify Request').item.json;
const status = Number($json.statusCode) || null;
const body = $json.body;
const success = status >= 200 && status < 300 && body?.id === p.provider_message_id && Array.isArray(body.labelIds) && p.modify_body.addLabelIds.every(id => body.labelIds.includes(id)) && p.modify_body.removeLabelIds.every(id => !body.labelIds.includes(id));
const transient = status === 429 || (status !== null && status >= 500) || (status === 403 && ['rateLimitExceeded','userRateLimitExceeded'].includes(body?.error?.errors?.[0]?.reason));
const error = success ? null : status === null || (status >= 200 && status < 300) ? 'verify_mailbox_before_replay' : transient ? 'transient_gmail_error_retry_later' : 'gmail_modify_failed';
return { json:{ ...p,status:success ? 'applied' : 'needs_review',decision:success ? p.decision : 'needs_review',reasons:success ? p.reasons : [...p.reasons,error],delivery:{ attempted:true,http_status:status,error_code:error,retryable:transient,verified:success } } };
